package stack

import (
	"fmt"
	"regexp"
	"sort"
	"strings"
)

// Components are the supporting services a catalog template asks for by name
// ("with: {postgres: {}}") instead of writing them out: databases, caches and
// object storage. Each is defined once here, with a maintained image, a
// health check, a named volume and credentials generated by Pier, so a fix or
// an upgrade reaches every template that uses it.
//
// A template refers to a component's connection details with placeholders in
// its services and inline files, {{<component>.<field>}}, for example
// {{postgres.url}}; the fields of each kind are listed in componentKinds.

// ComponentOptions are the knobs a template may turn on a component. The key
// it is declared under in "with:" is the name of its service.
type ComponentOptions struct {
	// Kind is the component (postgres, redis, …); it defaults to the key.
	Kind string `yaml:"kind"`
	// Version is the major version, when the application needs a specific one.
	Version string `yaml:"version"`
	// Flavor picks a variant image: "pgvector" or "postgis" for postgres.
	Flavor string `yaml:"flavor"`
	// Database is the database created on first start ("app" by default).
	Database string `yaml:"database"`
	// User is a fixed user name, for applications that expect one; by
	// default Pier generates it.
	User string `yaml:"user"`
	// Password protects a cache (redis, valkey) with a generated password.
	Password bool `yaml:"password"`
	// Buckets are created on first start of an object store (minio).
	Buckets []string `yaml:"buckets"`
	// Args are extra server options (postgres -c settings, mysql and mariadb
	// flags, redis and valkey directives), for applications that need them.
	Args []string `yaml:"args"`
	// Env adds variables to the component (TZ, POSTGRES_INITDB_ARGS…).
	Env map[string]string `yaml:"env"`
	// ShmSize is the shared memory of the container (postgres parallel queries).
	ShmSize string `yaml:"shm_size"`
}

// argsKinds take Args; the others refuse them.
var argsKinds = map[string]bool{"postgres": true, "mysql": true, "mariadb": true, "redis": true, "valkey": true}

// finish applies the options every kind shares to a built service: extra
// environment, shared memory and server arguments.
func finish(service *orderedMap, kind string, options ComponentOptions) {
	if len(options.Env) > 0 {
		environment, _ := service.values["environment"].([]any)
		keys := make([]string, 0, len(options.Env))
		for key := range options.Env {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			environment = append(environment, key+"="+options.Env[key])
		}
		service.set("environment", environment)
	}
	if options.ShmSize != "" {
		service.set("shm_size", options.ShmSize)
	}
	if len(options.Args) == 0 {
		return
	}
	switch kind {
	case "postgres":
		command := []any{"postgres"}
		for _, arg := range options.Args {
			command = append(command, arg)
		}
		service.set("command", command)
	case "mysql", "mariadb":
		command := []any{}
		for _, arg := range options.Args {
			command = append(command, arg)
		}
		service.set("command", command)
	case "redis", "valkey":
		switch command := service.values["command"].(type) {
		case []any:
			if len(command) == 3 && command[0] == "sh" {
				command[2] = command[2].(string) + " " + strings.Join(options.Args, " ")
			} else {
				for _, arg := range options.Args {
					command = append(command, arg)
				}
				service.set("command", command)
			}
		}
	}
}

// componentKind builds the service of one kind of component and the values
// templates may read from it.
type componentKind struct {
	versions       []string
	defaultVersion string
	build          func(name string, options ComponentOptions) (services []namedService, fields map[string]string)
}

// namedService is a compose service with its name, ready to be written.
type namedService struct {
	name       string
	definition orderedMap
}

// orderedMap is a compose mapping that keeps the order keys were added in,
// so generated files read naturally (image first, health check last).
type orderedMap struct {
	keys   []string
	values map[string]any
}

func newMap() orderedMap { return orderedMap{values: map[string]any{}} }

func (m *orderedMap) set(key string, value any) {
	if _, exists := m.values[key]; !exists {
		m.keys = append(m.keys, key)
	}
	m.values[key] = value
}

func (m orderedMap) has(key string) bool {
	_, exists := m.values[key]
	return exists
}

var componentKinds = map[string]componentKind{
	"postgres":   {versions: []string{"14", "15", "16", "17", "18"}, defaultVersion: "17", build: postgresComponent},
	"mysql":      {versions: []string{"8.0", "8.4"}, defaultVersion: "8.4", build: mysqlComponent},
	"mariadb":    {versions: []string{"10.11", "11.4", "11.8"}, defaultVersion: "11.4", build: mariadbComponent},
	"redis":      {versions: []string{"7.2", "7.4", "8.2"}, defaultVersion: "7.4", build: cacheComponent("redis")},
	"valkey":     {versions: []string{"8.1"}, defaultVersion: "8.1", build: cacheComponent("valkey")},
	"mongo":      {versions: []string{"6.0", "7.0", "8.0"}, defaultVersion: "7.0", build: mongoComponent},
	"clickhouse": {versions: []string{"25.8"}, defaultVersion: "25.8", build: clickhouseComponent},
	"minio":      {versions: []string{"2026-08"}, defaultVersion: "2026-08", build: minioComponent},
}

// minioImages pins the object store and its client. MinIO stopped publishing
// community images in 2025; pgsty rebuilds the dated releases from source.
var minioImages = map[string][2]string{
	"2026-08": {"pgsty/minio:RELEASE.2026-08-04T00-00-00Z", "pgsty/mc:RELEASE.2026-11-09T00-00-00Z"},
}

// magicSuffix turns a service name into the tail of a magic variable.
func magicSuffix(service string) string {
	return strings.ToUpper(strings.NewReplacer("-", "", "_", "", ".", "").Replace(service))
}

// credentials are the user (generated unless the template fixes one) and the
// generated password of a component.
func credentials(name string, options ComponentOptions) (user, password string) {
	suffix := magicSuffix(name)
	user = "${PIER_USER_" + suffix + "}"
	if options.User != "" {
		user = options.User
	}
	return user, "${PIER_PASSWORD_" + suffix + "}"
}

func healthcheck(test []any, interval string) orderedMap {
	check := newMap()
	check.set("test", test)
	check.set("interval", interval)
	check.set("timeout", "5s")
	check.set("retries", 10)
	check.set("start_period", "20s")
	return check
}

func postgresComponent(name string, options ComponentOptions) ([]namedService, map[string]string) {
	user, password := credentials(name, options)
	database := options.Database
	image := map[string]string{
		"":         "postgres:%s-alpine",
		"pgvector": "pgvector/pgvector:pg%s",
		"postgis":  "postgis/postgis:%s-3.7-alpine",
	}[options.Flavor]
	service := newMap()
	service.set("image", fmt.Sprintf(image, options.Version))
	service.set("environment", []any{"POSTGRES_USER=" + user, "POSTGRES_PASSWORD=" + password, "POSTGRES_DB=" + database})
	// From version 18 the image keeps its data in a versioned folder under
	// /var/lib/postgresql, so the volume mounts the parent.
	dataPath := "/var/lib/postgresql/data"
	if options.Version >= "18" {
		dataPath = "/var/lib/postgresql"
	}
	service.set("volumes", []any{name + "-data:" + dataPath})
	service.set("healthcheck", healthcheck([]any{"CMD-SHELL", "pg_isready -U \"$$POSTGRES_USER\" -d \"$$POSTGRES_DB\""}, "5s"))
	return []namedService{{name, service}}, map[string]string{
		"host": name, "port": "5432", "user": user, "password": password, "database": database,
		"url": "postgresql://" + user + ":" + password + "@" + name + ":5432/" + database,
	}
}

func mysqlComponent(name string, options ComponentOptions) ([]namedService, map[string]string) {
	return sqlComponent(name, options, "mysql:"+options.Version, "MYSQL",
		[]any{"CMD-SHELL", "mysqladmin ping -h 127.0.0.1 -u root --password=\"$$MYSQL_ROOT_PASSWORD\" --silent"})
}

func mariadbComponent(name string, options ComponentOptions) ([]namedService, map[string]string) {
	return sqlComponent(name, options, "mariadb:"+options.Version, "MARIADB",
		[]any{"CMD", "healthcheck.sh", "--connect", "--innodb_initialized"})
}

// sqlComponent is MySQL or MariaDB: same variables under each image's prefix.
func sqlComponent(name string, options ComponentOptions, image, prefix string, test []any) ([]namedService, map[string]string) {
	user, password := credentials(name, options)
	rootPassword := "${PIER_PASSWORD_" + magicSuffix(name) + "ROOT}"
	service := newMap()
	service.set("image", image)
	service.set("environment", []any{
		prefix + "_ROOT_PASSWORD=" + rootPassword, prefix + "_DATABASE=" + options.Database,
		prefix + "_USER=" + user, prefix + "_PASSWORD=" + password,
	})
	service.set("volumes", []any{name + "-data:/var/lib/mysql"})
	service.set("healthcheck", healthcheck(test, "5s"))
	return []namedService{{name, service}}, map[string]string{
		"host": name, "port": "3306", "user": user, "password": password, "root_password": rootPassword,
		"database": options.Database,
		"url":      "mysql://" + user + ":" + password + "@" + name + ":3306/" + options.Database,
	}
}

// cacheComponent is Redis or Valkey: an append-only cache, optionally with a
// password read from the environment (never written on the command line,
// where any read token could see it).
func cacheComponent(kind string) func(string, ComponentOptions) ([]namedService, map[string]string) {
	images := map[string]string{"redis": "redis:%s-alpine", "valkey": "valkey/valkey:%s-alpine"}
	return func(name string, options ComponentOptions) ([]namedService, map[string]string) {
		service := newMap()
		service.set("image", fmt.Sprintf(images[kind], options.Version))
		server, client := kind+"-server", kind+"-cli"
		fields := map[string]string{"host": name, "port": "6379", "password": "", "url": "redis://" + name + ":6379"}
		if options.Password {
			password := "${PIER_PASSWORD_" + magicSuffix(name) + "}"
			service.set("environment", []any{"CACHE_PASSWORD=" + password})
			service.set("command", []any{"sh", "-c", "exec " + server + " --appendonly yes --requirepass \"$$CACHE_PASSWORD\""})
			service.set("volumes", []any{name + "-data:/data"})
			service.set("healthcheck", healthcheck([]any{"CMD-SHELL", client + " -a \"$$CACHE_PASSWORD\" --no-auth-warning ping | grep -q PONG"}, "5s"))
			fields["password"] = password
			fields["url"] = "redis://:" + password + "@" + name + ":6379"
		} else {
			service.set("command", []any{server, "--appendonly", "yes"})
			service.set("volumes", []any{name + "-data:/data"})
			service.set("healthcheck", healthcheck([]any{"CMD", client, "ping"}, "5s"))
		}
		return []namedService{{name, service}}, fields
	}
}

func mongoComponent(name string, options ComponentOptions) ([]namedService, map[string]string) {
	user, password := credentials(name, options)
	service := newMap()
	service.set("image", "mongo:"+options.Version)
	service.set("environment", []any{
		"MONGO_INITDB_ROOT_USERNAME=" + user, "MONGO_INITDB_ROOT_PASSWORD=" + password,
		"MONGO_INITDB_DATABASE=" + options.Database,
	})
	service.set("volumes", []any{name + "-data:/data/db"})
	service.set("healthcheck", healthcheck([]any{"CMD", "mongosh", "--quiet", "--eval", "db.adminCommand('ping').ok"}, "10s"))
	return []namedService{{name, service}}, map[string]string{
		"host": name, "port": "27017", "user": user, "password": password, "database": options.Database,
		"url": "mongodb://" + user + ":" + password + "@" + name + ":27017/" + options.Database + "?authSource=admin",
	}
}

func clickhouseComponent(name string, options ComponentOptions) ([]namedService, map[string]string) {
	user, password := credentials(name, options)
	service := newMap()
	service.set("image", "clickhouse/clickhouse-server:"+options.Version+"-alpine")
	service.set("environment", []any{
		"CLICKHOUSE_USER=" + user, "CLICKHOUSE_PASSWORD=" + password, "CLICKHOUSE_DB=" + options.Database,
		"CLICKHOUSE_DEFAULT_ACCESS_MANAGEMENT=1",
	})
	service.set("volumes", []any{name + "-data:/var/lib/clickhouse"})
	limits := newMap()
	nofile := newMap()
	nofile.set("soft", 262144)
	nofile.set("hard", 262144)
	limits.set("nofile", nofile)
	service.set("ulimits", limits)
	service.set("healthcheck", healthcheck([]any{"CMD-SHELL", "wget -q --spider http://127.0.0.1:8123/ping || exit 1"}, "5s"))
	return []namedService{{name, service}}, map[string]string{
		"host": name, "port": "8123", "native_port": "9000", "user": user, "password": password,
		"database": options.Database,
		"url":      "http://" + user + ":" + password + "@" + name + ":8123/" + options.Database,
	}
}

// minioComponent is S3-compatible storage; with Buckets, a one-shot service
// creates them before the application starts.
func minioComponent(name string, options ComponentOptions) ([]namedService, map[string]string) {
	user, password := credentials(name, options)
	images := minioImages[options.Version]
	service := newMap()
	service.set("image", images[0])
	service.set("command", []any{"server", "/data", "--console-address", ":9001"})
	service.set("environment", []any{"MINIO_ROOT_USER=" + user, "MINIO_ROOT_PASSWORD=" + password})
	service.set("volumes", []any{name + "-data:/data"})
	service.set("healthcheck", healthcheck([]any{"CMD", "mc", "ready", "local"}, "5s"))
	services := []namedService{{name, service}}
	if len(options.Buckets) > 0 {
		buckets := append([]string(nil), options.Buckets...)
		sort.Strings(buckets)
		script := "mc alias set store http://" + name + ":9000 \"$$MINIO_ROOT_USER\" \"$$MINIO_ROOT_PASSWORD\""
		for _, bucket := range buckets {
			script += " && mc mb --ignore-existing store/" + bucket
		}
		init := newMap()
		init.set("image", images[1])
		init.set("restart", "no")
		init.set("entrypoint", []any{"sh", "-c", script})
		init.set("environment", []any{"MINIO_ROOT_USER=" + user, "MINIO_ROOT_PASSWORD=" + password})
		dependency := newMap()
		condition := newMap()
		condition.set("condition", "service_healthy")
		dependency.set(name, condition)
		init.set("depends_on", dependency)
		services = append(services, namedService{name + "-init", init})
	}
	return services, map[string]string{
		"host": name, "port": "9000", "console_port": "9001", "user": user, "password": password,
		"endpoint": "http://" + name + ":9000",
	}
}

var userName = regexp.MustCompile(`^[a-z_][a-z0-9_]{0,62}$`)

// buildComponent checks the options of the component declared as name and
// builds it.
func buildComponent(name string, options ComponentOptions) ([]namedService, map[string]string, error) {
	kind := options.Kind
	if kind == "" {
		kind = name
	}
	definition, known := componentKinds[kind]
	if !known {
		return nil, nil, fmt.Errorf("unknown component %q", kind)
	}
	if options.Version == "" {
		options.Version = definition.defaultVersion
	}
	supported := false
	for _, version := range definition.versions {
		supported = supported || version == options.Version
	}
	if !supported {
		return nil, nil, fmt.Errorf("component %s has no version %q (supported: %s)", kind, options.Version, strings.Join(definition.versions, ", "))
	}
	if options.Flavor != "" && (kind != "postgres" || (options.Flavor != "pgvector" && options.Flavor != "postgis")) {
		return nil, nil, fmt.Errorf("component %s has no flavor %q", kind, options.Flavor)
	}
	if options.Password && kind != "redis" && kind != "valkey" {
		return nil, nil, fmt.Errorf("component %s does not take a password option", kind)
	}
	if options.User != "" && (kind == "redis" || kind == "valkey") {
		return nil, nil, fmt.Errorf("component %s has no user", kind)
	}
	if options.User != "" && !userName.MatchString(options.User) {
		return nil, nil, fmt.Errorf("component %s: invalid user %q", kind, options.User)
	}
	if len(options.Buckets) > 0 && kind != "minio" {
		return nil, nil, fmt.Errorf("component %s does not create buckets", kind)
	}
	if options.Database == "" {
		options.Database = "app"
	}
	if !serviceNamePattern.MatchString(name) {
		return nil, nil, fmt.Errorf("component %s: invalid service name %q", kind, name)
	}
	if len(options.Args) > 0 && !argsKinds[kind] {
		return nil, nil, fmt.Errorf("component %s does not take args", kind)
	}
	services, fields := definition.build(name, options)
	finish(&services[0].definition, kind, options)
	return services, fields, nil
}
